  ('p-biarritz-steel-24x12-warm-cedar-fr', 'p-biarritz-steel-24x12-warm-cedar', 'fr', 'Pergola Biarritz 24×12 — acier cèdre chaud', 'Structure acier, 24×12 ft.', 'Biarritz 24×12 ft en acier, finition cèdre chaud. Aluminium brossé, tenue mer. Structure autoportée, kit livré prêt à monter avec quincaillerie et notice détaillée.', NULL),
  ('p-biarritz-steel-24x12-warm-cedar-en', 'p-biarritz-steel-24x12-warm-cedar', 'en', 'Biarritz pergola 24×12 — steel, warm cedar', 'Steel frame, 24×12 ft.', 'Biarritz 24×12 ft in steel, warm cedar finish. Brushed aluminium, sea-grade. Free-standing kit, delivered ready to assemble with hardware and detailed instructions.', NULL),
  ('p-napa-steel-24x12-barnwood-fr', 'p-napa-steel-24x12-barnwood', 'fr', 'Pergola Napa 24×12 — acier barnwood', 'Structure acier, 24×12 ft.', 'Napa 24×12 ft en acier, finition barnwood. Aluminium sobre, style vigne californienne. Structure autoportée, kit livré prêt à monter avec quincaillerie et notice détaillée.', NULL),
